    "weapon.desc.pisau-taktis": "Versatile close-range melee tool for silent takedowns, tactical movement speed, and critical clutch backstabs.",
    "weapon.desc.classic": "Lightweight and versatile standard-issue sidearm, equipped with semi-auto fire and an alternate 3-round burst.",
    "weapon.desc.shorty": "Compact double-barrel shotgun designed for devastating point-blank ambushes in tight corners.",
    "weapon.desc.frenzy": "Rapid-firing automatic machine pistol tailored for high-tempo aggressive rushes and close-quarters duels.",
    "weapon.desc.ghost": "Silenced tactical sidearm delivering clean headshot accuracy and high mobility without revealing tracer fire.",
    "weapon.desc.sheriff": "High-caliber six-shooter revolver capable of lethal one-tap headshots in skilled marksman hands.",
    "weapon.desc.bandit": "Heavy close-range sidearm built for hard-hitting punch and aggressive round openers.",
    "weapon.desc.stinger": "Ultra-fast submachine gun delivering blistering sustained fire and burst-fire zoom for quick entries.",
    "weapon.desc.spectre": "All-round silenced submachine gun balancing tight recoil control and high damage output at medium range.",
    "weapon.desc.bucky": "Pump-action shotgun with an alternative airburst canister shell for extended close-range lethality.",
    "weapon.desc.judge": "Fully automatic drum-fed combat shotgun engineered for rapid room clearing and area lockdown.",
    "weapon.desc.bulldog": "Cost-effective bullpup rifle offering full-auto hipfire and accurate 3-round bursts when aiming down sights.",
    "weapon.desc.guardian": "Semi-automatic designated marksman rifle boasting maximum wall penetration and devastating headshot punch.",
    "weapon.desc.phantom": "Suppressed assault rifle featuring rapid fire rate, tracerless stealth rounds, and silky recoil recovery.",
    "weapon.desc.vandal": "High-powered battle rifle renowned for its lethal one-shot headshot capability at any combat range.",
    "weapon.desc.marshal": "Nimble lever-action sniper rifle with swift handling speed and lethal stopping power on eco rounds.",
    "weapon.desc.outlaw": "Break-action double-barrel sniper rifle engineered to punish half-armor opponents with brutal per-shot damage.",
    "weapon.desc.operator": "Heavy anti-material bolt-action sniper rifle guaranteeing instant one-shot elimination above the waist.",
    "weapon.desc.ares": "Light machine gun with a spooling fire rate and heavy wall penetration, ideal for suppressing wall-bang angles.",
    "weapon.desc.odin": "Devastating 100-round heavy machine gun that tears through terrain and denies enemy site executes.",

