    "news.title": "News & Events",
    "news.eyebrow": "FRAG OR DIE: LATEST BATTLEFIELD INTEL",
    "news.lede": "From the newest patches, hyped skin collections, to global esports circuits, all VALORANT intel in one place. Click any briefing card for full coverage.",
    "news.filterAria": "Filter news category",
    "news.backToNews": "← Back to News",
