export function getLanguage(): Lang {
  if (typeof localStorage !== "undefined") {
    const saved = localStorage.getItem("unscoped_lang");
    if (saved === "id" || saved === "en") return saved;
  }
  return "id";
}

export function setLanguage(lang: Lang) {
  if (typeof localStorage !== "undefined") {
    localStorage.setItem("unscoped_lang", lang);
  }
  document.documentElement.lang = lang;
  applyTranslations(lang);
  updateLangButtons(lang);
  window.dispatchEvent(new CustomEvent("langchange", { detail: { lang } }));
}

export function applyTranslations(lang: Lang) {
  const dict = translations[lang] || translations.id;

  // Replace textContent via data-i18n
  document.querySelectorAll<HTMLElement>("[data-i18n]").forEach((el) => {
    const key = el.dataset.i18n;
    if (key && dict[key] !== undefined) {
      el.textContent = dict[key];
    }
  });

  // Replace innerHTML via data-i18n-html
  document.querySelectorAll<HTMLElement>("[data-i18n-html]").forEach((el) => {
    const key = el.dataset.i18nHtml;
    if (key && dict[key] !== undefined) {
      el.innerHTML = dict[key];
    }
  });

  // Replace placeholders
  document.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("[data-i18n-placeholder]").forEach((el) => {
    const key = el.dataset.i18nPlaceholder;
    if (key && dict[key] !== undefined) {
      el.placeholder = dict[key];
    }
  });

  // Replace title attributes
  document.querySelectorAll<HTMLElement>("[data-i18n-title]").forEach((el) => {
    const key = el.dataset.i18nTitle;
    if (key && dict[key] !== undefined) {
      el.title = dict[key];
    }
  });

  // Replace aria-label attributes
  document.querySelectorAll<HTMLElement>("[data-i18n-aria]").forEach((el) => {
    const key = el.dataset.i18nAria;
    if (key && dict[key] !== undefined) {
      el.setAttribute("aria-label", dict[key]);
    }
  });

  // Replace alt attributes
  document.querySelectorAll<HTMLImageElement>("[data-i18n-alt]").forEach((el) => {
    const key = el.dataset.i18nAlt;
    if (key && dict[key] !== undefined) {
      el.alt = dict[key];
    }
  });

  // Replace dynamic agent aria-labels
  document.querySelectorAll<HTMLElement>("[data-i18n-aria-agent]").forEach((el) => {
    const name = el.dataset.agentName || "";
    const prefix = dict["agents.viewProfile"] || (lang === "en" ? "View agent profile" : "Lihat profil agent");
    el.setAttribute("aria-label", `${prefix} ${name}`);
  });
}

export function updateLangButtons(lang: Lang) {
  document.querySelectorAll<HTMLButtonElement>("[data-lang-btn]").forEach((btn) => {
    const isCurrent = btn.dataset.langBtn === lang;
    btn.classList.toggle("is-active", isCurrent);
    btn.setAttribute("aria-pressed", String(isCurrent));
  });
}

export function setupI18n() {
  const current = getLanguage();
  document.documentElement.lang = current;
  applyTranslations(current);
  updateLangButtons(current);

  document.querySelectorAll<HTMLButtonElement>("[data-lang-btn]").forEach((btn) => {
    if (btn.dataset.bound === "1") return;
    btn.dataset.bound = "1";
    btn.addEventListener("click", () => {
      const target = btn.dataset.langBtn as Lang;
      if (target) setLanguage(target);
    });
  });
}
